// Validate and extract incoming payload
const body = $input.first().json.body || $input.first().json;

const age          = parseInt(body.age) || 8;
const level        = body.level        || 'CE2';
const activityType = body.activity_type || 'logique';
const objective    = body.objective    || 'Développer la pensée logique';
const outputDir    = body.output_dir   || './outputs';

// Basic validation
if (age < 5 || age > 12) {
  throw new Error(`Age invalide : ${age}. Attendu entre 5 et 12.`);
}

return [
  {
    json: {
      age,
      level,
      activity_type: activityType,
      objective,
      output_dir: outputDir,
      validated_at: new Date().toISOString()
    }
  }
];

// Parse Python stdout output
const stdout = $input.first().json.stdout || '{}';
let result;

try {
  result = JSON.parse(stdout.trim());
} catch (e) {
  result = {
    error: 'Failed to parse Python output',
    raw: stdout,
    success: false
  };
}

const success = !!result.pdf_path && !result.error;

return [
  {
    json: {
      success,
      pdf_path:      result.pdf_path     || null,
      duration_sec:  result.duration_sec || null,
      fallback_used: result.fallback_used || false,
      rag_chars:     result.rag_chars    || 0,
      log_path:      result.log_path     || null,
      error:         result.error        || null,
      generated_at:  new Date().toISOString()
    }
  }
];
